// EXI Engine Adapter for V2G Message Encoding/Decoding
//
// This adapter bridges TTCN-3 test cases with the pre-encoded EXI payload library
// generated by exi_harvester.py from iso15118-master.
//
// Payload library resolution:
//   1. EXI_PAYLOAD_LIBRARY env var (absolute path, highest priority)
//   2. ../../exi_payload_library.json  (relative to build/bin/ where TestExecutable runs)
//   3. agent/test_code/examples/demo/exi_payload_library.json (relative to repo root)
//
// SessionID patching: Four messages (session_setup/stop req/res) store
// "0000000000000000" as a placeholder. encode(key, session_id) replaces it.

#include "ExiCodecAdapter.hh"
#include "exi_codec_logger.hh"

#include <fstream>
#include <sstream>
#include <algorithm>
#include <cctype>
#include <cstring>
#include <cstdlib>
#include <vector>
#include <map>
#include <functional>

// ============================================================================
// JSON parsing helpers (no external dependency)
// ============================================================================

namespace {

std::string json_unescape(const std::string& s) {
    std::string r;
    r.reserve(s.size());
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            char c = s[++i];
            switch (c) {
                case '"': case '\\': case '/': r += c; break;
                case 'b': r += '\b'; break;
                case 'f': r += '\f'; break;
                case 'n': r += '\n'; break;
                case 'r': r += '\r'; break;
                case 't': r += '\t'; break;
                default: r += c; break;
            }
        } else {
            r += s[i];
        }
    }
    return r;
}

std::string json_get_string(const std::string& obj, const std::string& key) {
    std::string qkey = "\"" + key + "\"";
    size_t pos = obj.find(qkey);
    if (pos == std::string::npos) return "";
    size_t colon = obj.find(':', pos);
    if (colon == std::string::npos) return "";
    size_t q1 = obj.find('"', colon);
    if (q1 == std::string::npos) return "";
    size_t q2 = q1 + 1;
    while (q2 < obj.size()) {
        if (obj[q2] == '\\') { q2 += 2; continue; }
        if (obj[q2] == '"') break;
        ++q2;
    }
    return json_unescape(obj.substr(q1 + 1, q2 - q1 - 1));
}

bool json_get_bool(const std::string& obj, const std::string& key, bool def = false) {
    std::string qkey = "\"" + key + "\"";
    size_t pos = obj.find(qkey);
    if (pos == std::string::npos) return def;
    size_t colon = obj.find(':', pos);
    if (colon == std::string::npos) return def;
    size_t val_start = colon + 1;
    while (val_start < obj.size() && std::isspace(obj[val_start])) ++val_start;
    if (val_start < obj.size() && obj[val_start] == 't') return true;
    return false;
}

std::vector<std::string> json_get_string_array(const std::string& obj, const std::string& key) {
    std::vector<std::string> result;
    std::string qkey = "\"" + key + "\"";
    size_t pos = obj.find(qkey);
    if (pos == std::string::npos) return result;
    size_t bracket = obj.find('[', pos);
    if (bracket == std::string::npos) return result;
    size_t depth = 1, i = bracket + 1;
    while (i < obj.size() && depth > 0) {
        if (obj[i] == '"' && depth == 1) {
            size_t q2 = i + 1;
            while (q2 < obj.size()) {
                if (obj[q2] == '\\') { q2 += 2; continue; }
                if (obj[q2] == '"') break;
                ++q2;
            }
            result.push_back(json_unescape(obj.substr(i + 1, q2 - i - 1)));
            i = q2 + 1;
        } else if (obj[i] == '[' || obj[i] == '{') {
            ++depth; ++i;
        } else if (obj[i] == ']' || obj[i] == '}') {
            --depth; ++i;
        } else {
            ++i;
        }
    }
    return result;
}

std::string json_get_object(const std::string& doc, const std::string& key) {
    std::string qkey = "\"" + key + "\"";
    size_t pos = doc.find(qkey);
    if (pos == std::string::npos) return "";
    size_t colon = doc.find(':', pos);
    if (colon == std::string::npos) return "";
    size_t brace = doc.find('{', colon);
    if (brace == std::string::npos) return "";
    size_t depth = 1, i = brace + 1;
    while (i < doc.size() && depth > 0) {
        if (doc[i] == '{' || doc[i] == '[') ++depth;
        else if (doc[i] == '}' || doc[i] == ']') { --depth; if (depth == 0) return doc.substr(brace, i - brace + 1); }
        ++i;
    }
    return "";
}

void json_for_each_entry(const std::string& obj,
                        const std::function<void(const std::string&, const std::string&)>& func) {
    size_t i = 0;
    while (i < obj.size() && std::isspace(obj[i])) ++i;
    if (i >= obj.size() || obj[i] != '{') return;
    ++i;
    while (i < obj.size()) {
        while (i < obj.size() && std::isspace(obj[i])) ++i;
        if (i >= obj.size() || obj[i] == '}') break;
        if (obj[i] == ',') { ++i; continue; }
        if (obj[i] != '"') { ++i; continue; }
        size_t q1 = i + 1, q2 = q1;
        while (q2 < obj.size() && obj[q2] != '"') {
            if (obj[q2] == '\\') ++q2;
            ++q2;
        }
        std::string key = json_unescape(obj.substr(q1, q2 - q1));
        i = q2 + 1;
        while (i < obj.size() && obj[i] != ':') ++i;
        if (i >= obj.size()) break;
        ++i;
        while (i < obj.size() && std::isspace(obj[i])) ++i;
        if (i >= obj.size()) break;
        if (obj[i] == '{') {
            size_t depth = 1, j = i + 1;
            while (j < obj.size() && depth > 0) {
                if (obj[j] == '{' || obj[j] == '[') ++depth;
                else if (obj[j] == '}' || obj[j] == ']') --depth;
                ++j;
            }
            func(key, obj.substr(i, j - i));
            i = j;
        } else if (obj[i] == '[') {
            size_t depth = 1, j = i + 1;
            while (j < obj.size() && depth > 0) {
                if (obj[j] == '[' || obj[j] == '{') ++depth;
                else if (obj[j] == ']' || obj[j] == '}') --depth;
                ++j;
            }
            func(key, obj.substr(i, j - i));
            i = j;
        } else {
            size_t j = i;
            while (j < obj.size() && obj[j] != ',' && obj[j] != '}') ++j;
            func(key, obj.substr(i, j - i));
            i = j;
        }
    }
}

} // anonymous namespace

// ============================================================================
// ExiCodecAdapter public implementation
// ============================================================================

ExiCodecAdapter::ExiCodecAdapter()
    : library_loaded_(false),
      library_path_(),
      initialized_(false),
      last_error_()
{}

ExiCodecAdapter& ExiCodecAdapter::instance() {
    static ExiCodecAdapter inst;
    return inst;
}

bool ExiCodecAdapter::initialize(bool /*schema_aware*/) {
    initialized_ = true;

    const char* env_path = std::getenv("EXI_PAYLOAD_LIBRARY");
    if (env_path && env_path[0]) {
        return load_library(env_path);
    }

    static const char* const SEARCH_PATHS[] = {
        "../../exi_payload_library.json",
        "agent/test_code/examples/demo/exi_payload_library.json",
    };

    for (const char* rel_path : SEARCH_PATHS) {
        std::ifstream test(rel_path, std::ios::binary);
        if (test.good()) {
            test.close();
            library_path_ = rel_path;
            if (load_library(library_path_)) {
                std::ostringstream oss;
                oss << "loaded " << payloads_.size() << " payloads from " << library_path_;
                LOG_INFO(oss.str());
                return true;
            }
        }
    }

    LOG_WARN("no payload library found; encode/decode will use pass-through");
    return true;
}

bool ExiCodecAdapter::load_library(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        last_error_ = "Cannot open payload library: " + path;
        LOG_ERROR(last_error_);
        return false;
    }

    std::stringstream ss;
    ss << file.rdbuf();
    std::string json = ss.str();
    file.close();

    payloads_.clear();

    std::string messages_obj = json_get_object(json, "messages");
    if (messages_obj.empty()) {
        last_error_ = "Payload library has no 'messages' object";
        LOG_ERROR(last_error_);
        return false;
    }

    json_for_each_entry(messages_obj, [this](const std::string& key, const std::string& val) {
        PayloadEntry entry;
        entry.wire_hex        = json_get_string(val, "wire_hex");
        entry.exi_payload_hex = json_get_string(val, "exi_payload_hex");
        entry.namespace_       = json_get_string(val, "namespace");
        entry.payload_type    = json_get_string(val, "v2gtp_payload_type");
        entry.is_dynamic      = json_get_bool(val, "is_dynamic", false);
        entry.dynamic_fields  = json_get_string_array(val, "dynamic_fields");
        payloads_[key] = entry;
    });

    library_path_   = path;
    library_loaded_ = true;

    std::ostringstream oss;
    oss << "parsed " << payloads_.size() << " payload entries from " << path;
    LOG_INFO(oss.str());
    return true;
}

ExiCodecResult ExiCodecAdapter::encode(const std::string& message_key,
                                      const std::string& session_id,
                                      std::vector<uint8_t>& wire_output) {
    ExiCodecResult result;
    result.success = false;
    result.bytes_consumed = 0;

    if (!initialized_) {
        last_error_ = "Codec not initialized";
        result.error_message = last_error_;
        return result;
    }

    auto it = payloads_.find(message_key);
    if (it == payloads_.end()) {
        last_error_ = "Unknown message key: " + message_key;
        result.error_message = last_error_;
        LOG_ERROR(last_error_);
        return result;
    }

    wire_output = hex_to_bytes(it->second.wire_hex);

    if (!session_id.empty() && it->second.is_dynamic) {
        wire_output = patch_session_id(wire_output, session_id);
    }

    result.success = true;
    result.bytes_consumed = static_cast<int>(wire_output.size());

    std::ostringstream oss;
    oss << "encode(key=" << message_key
        << ", session_id=" << (session_id.empty() ? "(none)" : session_id)
        << ") -> " << result.bytes_consumed << " bytes";
    LOG_DEBUG(oss.str());

    return result;
}

void ExiCodecAdapter::encode(const char* message_key, const std::string& session_id,
                             std::vector<uint8_t>& wire_output) {
    encode(std::string(message_key), session_id, wire_output);
}

ExiCodecResult ExiCodecAdapter::decode(const std::vector<uint8_t>& /*exi_data*/,
                                      std::vector<uint8_t>& xml_output) {
    ExiCodecResult result;
    result.success = true;
    result.bytes_consumed = 0;
    xml_output.clear();
    return result;
}

std::vector<uint8_t> ExiCodecAdapter::get_wire_bytes(const std::string& key) {
    auto it = payloads_.find(key);
    if (it == payloads_.end()) return {};
    return hex_to_bytes(it->second.wire_hex);
}

std::vector<uint8_t> ExiCodecAdapter::get_exi_bytes(const std::string& key) {
    auto it = payloads_.find(key);
    if (it == payloads_.end()) return {};
    return hex_to_bytes(it->second.exi_payload_hex);
}

bool ExiCodecAdapter::has_key(const std::string& key) const {
    return payloads_.find(key) != payloads_.end();
}

std::vector<std::string> ExiCodecAdapter::available_keys() const {
    std::vector<std::string> keys;
    for (const auto& kv : payloads_) keys.push_back(kv.first);
    return keys;
}

void ExiCodecAdapter::set_options(const ExiCodecOptions& options) {
    options_ = options;
}

// ============================================================================
// Private helpers
// ============================================================================

std::vector<uint8_t> ExiCodecAdapter::hex_to_bytes(const std::string& hex) {
    std::vector<uint8_t> result;
    result.reserve(hex.size() / 2);
    for (size_t i = 0; i + 1 < hex.size(); i += 2) {
        unsigned int byte = 0;
        std::string byte_str = hex.substr(i, 2);
        std::stringstream ss(byte_str);
        ss >> std::hex >> byte;
        result.push_back(static_cast<uint8_t>(byte));
    }
    return result;
}

std::vector<uint8_t> ExiCodecAdapter::patch_session_id(
        const std::vector<uint8_t>& wire_bytes,
        const std::string& new_session_id) const {

    if (wire_bytes.size() < 18) return wire_bytes;

    std::vector<uint8_t> result = wire_bytes;

    // Normalize: strip separators from new_session_id
    std::string clean_id;
    for (char c : new_session_id) {
        if (c != ':' && c != '-' && c != ' ') clean_id += c;
    }
    if (clean_id.size() < 16) clean_id = std::string(16 - clean_id.size(), '0') + clean_id;
    else if (clean_id.size() > 16) clean_id = clean_id.substr(clean_id.size() - 16);

    // V2GTP header = 8 bytes.  Search for "0000000000000000" in EXI portion.
    static const size_t SESSION_ID_BYTES = 8;
    static const size_t EXI_START = 8;

    for (size_t offset = EXI_START; offset + SESSION_ID_BYTES <= result.size(); ++offset) {
        bool is_zero = true;
        for (size_t j = 0; j < SESSION_ID_BYTES; ++j) {
            if (result[offset + j] != 0x00) { is_zero = false; break; }
        }
        if (is_zero) {
            for (size_t j = 0; j < SESSION_ID_BYTES; ++j) {
                unsigned int byte_val = 0;
                std::stringstream ss(clean_id.substr(j * 2, 2));
                ss >> std::hex >> byte_val;
                result[offset + j] = static_cast<uint8_t>(byte_val);
            }
            std::ostringstream oss;
            oss << "patched SessionID at byte " << offset << " with " << clean_id;
            LOG_DEBUG(oss.str());
            return result;
        }
    }

    LOG_WARN("SessionID placeholder not found in wire bytes");
    return result;
}
